// Build HTML tables from both sheets
const filtroRows = $('Read 1 Filtro').all();
const opsRows = $('Read Ops. Enviadas').all();

function buildTable(rows, label) {
  if (!rows || rows.length === 0) {
    return `<h3>${label}</h3><p>Sin datos.</p>`;
  }
  const headers = Object.keys(rows[0].json);
  const ths = headers.map(h => `<th style="border:1px solid #ccc;padding:6px 10px;background:#f5f5f5;text-align:left;font-size:12px">${h}</th>`).join('');
  const trs = rows.map(row => {
    const tds = headers.map(h => `<td style="border:1px solid #e0e0e0;padding:5px 10px;font-size:12px">${row.json[h] ?? ''}</td>`).join('');
    return `<tr>${tds}</tr>`;
  }).join('');
  return `
    <h3 style="color:#2d6a4f;margin:24px 0 8px">${label} (${rows.length} filas)</h3>
    <table style="border-collapse:collapse;width:100%;margin-bottom:16px">
      <thead><tr>${ths}</tr></thead>
      <tbody>${trs}</tbody>
    </table>`;
}

const now = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' });
const html = `
<!DOCTYPE html>
<html>
<body style="font-family:Arial,sans-serif;color:#333;max-width:900px;margin:0 auto;padding:16px">
  <h2 style="color:#2d6a4f">Kutxabank — Resumen diario (${now})</h2>
  ${buildTable(filtroRows, '1 Filtro')}
  ${buildTable(opsRows, 'Ops. Enviadas')}
  <p style="font-size:11px;color:#999;margin-top:32px">Enviado automáticamente por Banks Command Center.</p>
</body>
</html>`;

return [{ json: { html, subject: `Kutxabank diario — ${now}` } }];
